                              best_no_heat = s_M24h['global evidence']

                              def prior24bu(cube):
                                      cube[0] = 958*cube[0]
                                      cube[2] = cube[2]*(np.log10(S_disc(1.5)) + 2) - 2
                                      cube[3] = cube[3]*0.15
                                      cube[4] = cube[4]*0.19
                                      cube[5] = cube[5]*0.25
                                      cube[6] = cube[6]
                                      cube[7] = cube[7]*(1-cube[6])
                                      cube[8] = cube[8]*(3) + (np.log10(np.sum(10**(whitedwarfabundances))) - 1.5)
