N_outer = 23
while N_outer < 24:
    try:  # The double nested try/except is slightly horrible but allows me to catch (and ignore) unraised exceptions e.g. those caused by unexpected element combos
        try:
            PWDCode(N_outer, N_outer + 1, False)
        except Exception as e:
            print(e)
            raise e
    except:
        pass
    N_outer += 1

